export const BRAND_ORDER: BrandKey[] = [
  "typescript",
  "javascript",
  "html5",
  "css3",
  "python",
  "react",
  "nextjs",
  "redux",
  "tailwindcss",
  "sass",
  "framermotion",
  "electron",
  "nodejs",
  "postgresql",
  "mongodb",
  "prisma",
  "git",
  "docker",
  "nginx",
  "vitejs",
  "storybook",
  "vercel",
];

/** Maps free-text tech names (from data.ts) to a brand icon, when one exists. */
const ALIASES: Record<string, BrandKey> = {
  typescript: "typescript",
  javascript: "javascript",
  "javascript (es6+)": "javascript",
  html5: "html5",
  html: "html5",
  html5css3: "html5",
  css3: "css3",
  css: "css3",
  python: "python",
  react: "react",
  "react flow": "react",
  "next.js": "nextjs",
  nextjs: "nextjs",
  redux: "redux",
  "redux toolkit": "redux",
  "tailwind css": "tailwindcss",
  tailwindcss: "tailwindcss",
  sass: "sass",
  scss: "sass",
  "framer motion": "framermotion",
  framermotion: "framermotion",
  "framer-motion": "framermotion",
  motion: "framermotion",
  electron: "electron",
  "electron.js": "electron",
  electronjs: "electron",
  "node.js": "nodejs",
  nodejs: "nodejs",
  postgresql: "postgresql",
  postgres: "postgresql",
  mongodb: "mongodb",
  prisma: "prisma",
  git: "git",
  docker: "docker",
  nginx: "nginx",
  vite: "vitejs",
  vitejs: "vitejs",
  storybook: "storybook",
  "storybook.js": "storybook",
  vercel: "vercel",
};

export function brandKeyFor(name: string): BrandKey | null {
  return ALIASES[name.trim().toLowerCase()] ?? null;
}

export function BrandIcon({
  name,
  className,
  title,
}: {
  name: BrandKey;
  className?: string;
  title?: string;
}) {
  const icon = BRAND_ICONS[name];
  return (
    <svg
      viewBox={icon.viewBox}
      role="img"
      aria-label={title ?? icon.label}
      className={cn("size-full shrink-0", icon.mono && "text-foreground", className)}
      dangerouslySetInnerHTML={{ __html: icon.body }}
    />
  );
}
